import { useState } from 'react';
import { Button, Drawer, Divider } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavItem {
  key: NavKey;
  label: string;
  danger?: boolean;
}

const NAV_ITEMS: NavItem[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

interface NavDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const NavDrawer = ({ onNavigate }: NavDrawerProps) => {
  const [open, setOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <Button className="jx-button" onClick={() => setOpen(true)}>
        Меню
      </Button>

      <Drawer
        open={open}
        onClose={() => setOpen(false)}
        side="left"
        aria-label="Навигация"
      >
        <nav className="jx-nav" aria-label="Основная навигация">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.key}
              type="button"
              className="jx-menu-item"
              onClick={() => handleSelect(item.key)}
            >
              {item.label}
            </button>
          ))}

          <Divider className="jx-divider" />

          <button
            type="button"
            className="jx-menu-item jx-menu-item--danger"
            onClick={() => handleSelect('logout')}
          >
            Выйти
          </button>
        </nav>
      </Drawer>
    </>
  );
};

export default NavDrawer;

